package com.amalaei.engineering;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.net.Uri;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import java.math.BigDecimal;
import java.util.*;
import org.json.JSONObject;

/** دفتر ميداني مبسط: العهدة والتحصيلات والمصروفات، دون تحويله إلى نظام محاسبي معقد. */
public final class LedgerActivity extends BaseSecureActivity {
    private final int INK=0xff102a43,MUTED=0xff627487,TEAL=0xff0f766e,BG=0xfff5f7fa,LINE=0xffdae2ea;
    private Store store;private LinearLayout body;private Typeface font;
    @Override public void onCreate(Bundle state){super.onCreate(state);font=Typeface.createFromAsset(getAssets(),"fonts/Cairo.ttf");store=new Store(this);list();}
    @Override public void onPostCreate(Bundle state){super.onPostCreate(state);AppLanguage.apply(this);AppLanguage.watch(this);}
    @Override protected void onDestroy(){store.close();super.onDestroy();}
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private android.graphics.drawable.GradientDrawable shape(int color,int radius,int stroke){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
    private void base(String title){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);body.setPadding(dp(20),dp(14),dp(20),dp(28));body.setBackgroundColor(BG);scroll.addView(body);setContentView(scroll);body.setOnApplyWindowInsetsListener((v,i)->{int top,bottom;if(android.os.Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=i.getInsets(android.view.WindowInsets.Type.systemBars());top=bars.top;bottom=bars.bottom;}else{top=i.getSystemWindowInsetTop();bottom=i.getSystemWindowInsetBottom();}v.setPadding(dp(20),top+dp(14),dp(20),bottom+dp(28));return i;});body.addView(text(title,27));}
    private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTypeface(font);t.setTextColor(INK);t.setPadding(0,dp(4),0,dp(4));return t;}
    private void muted(String s){TextView t=text(s,14);t.setTextColor(MUTED);body.addView(t);}
    private LinearLayout card(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),dp(14),dp(16),dp(14));box.setBackground(shape(Color.WHITE,18,LINE));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(8),0,dp(8));body.addView(box,lp);return box;}
    private Button button(LinearLayout parent,String title,Runnable action,boolean primary){Button b=new Button(this);b.setText(title);b.setTextSize(14);b.setTypeface(font);b.setAllCaps(false);b.setTextColor(primary?Color.WHITE:TEAL);b.setBackground(shape(primary?TEAL:0xffe7f3f2,13,0));b.setOnClickListener(v->action.run());parent.addView(b,new LinearLayout.LayoutParams(-1,dp(48)));return b;}
    private EditText field(LinearLayout box,String label,String value,boolean number){TextView title=text(label,13);title.setTextColor(MUTED);box.addView(title);EditText e=new EditText(this);e.setTypeface(font);e.setText(value);e.setTextSize(16);e.setPadding(dp(12),dp(6),dp(12),dp(6));e.setBackground(shape(0xfff7f9fb,12,LINE));if(number)e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);box.addView(e,new LinearLayout.LayoutParams(-1,dp(52)));return e;}
    private void list(){base("الدفاتر");muted("سجّل العهدة والتحصيلات والمصروفات فورًا؛ الرصيد يتغير مع كل بند.");button(body,"+ إنشاء دفتر جديد",this::newNotebook,true);ArrayList<JSONObject> books=store.query("SELECT * FROM notebooks ORDER BY createdAt DESC");if(books.isEmpty())muted("أنشئ دفترًا مثل «عهدة المندوب» أو «مصروفات السيارة».");for(JSONObject book:books){ArrayList<JSONObject> rows=store.query("SELECT * FROM ledgerEntries WHERE notebookId=? ORDER BY at DESC,id DESC",String.valueOf(book.optLong("id")));LinearLayout box=card();box.addView(text(book.optString("name"),20));TextView balance=text("الرصيد الحالي  "+LedgerMath.money(LedgerMath.balance(book,rows)),20);balance.setTextColor(TEAL);box.addView(balance);TextView details=text("افتتاحي "+LedgerMath.money(LedgerMath.opening(book))+"  •  إضافات "+LedgerMath.money(LedgerMath.total(rows,"in"))+"  •  مصروفات "+LedgerMath.money(LedgerMath.total(rows,"out")),13);details.setTextColor(MUTED);box.addView(details);button(box,"فتح الدفتر",()->open(book.optLong("id")),false);}}
    private void newNotebook(){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(20),dp(8),dp(20),dp(8));EditText name=field(f,"اسم الدفتر", "",false),opening=field(f,"الرصيد الافتتاحي (اختياري)", "",true);new AlertDialog.Builder(this).setTitle("دفتر جديد").setView(f).setNegativeButton("إلغاء",null).setPositiveButton("إنشاء",(d,w)->{try{long id=store.saveNotebook(new JSONObject().put("name",name.getText().toString()).put("openingBalance",opening.getText().toString()));open(id);}catch(Exception e){alert(e);}}).show();}
    private void open(long id){ArrayList<JSONObject> found=store.query("SELECT * FROM notebooks WHERE id=?",String.valueOf(id));if(found.isEmpty()){list();return;}JSONObject book=found.get(0);ArrayList<JSONObject> rows=store.query("SELECT * FROM ledgerEntries WHERE notebookId=? ORDER BY at DESC,id DESC",String.valueOf(id));base(book.optString("name"));LinearLayout summary=card();TextView balance=text("الرصيد النقدي لدى المندوب  "+LedgerMath.money(LedgerMath.balance(book,rows)),23);balance.setTextColor(TEAL);summary.addView(balance);TextView totals=text("افتتاحي: "+LedgerMath.money(LedgerMath.opening(book))+"  •  تحصيل كاش: "+LedgerMath.money(LedgerMath.collections(rows,"cash"))+"\nتحصيل شبكة: "+LedgerMath.money(LedgerMath.collections(rows,"network"))+"  •  تحصيل تحويل: "+LedgerMath.money(LedgerMath.collections(rows,"transfer"))+"\nإجمالي التحصيلات: "+LedgerMath.money(LedgerMath.totalCollections(rows))+"  •  المصروفات: "+LedgerMath.money(LedgerMath.total(rows,"out"))+"\nصافي التحصيل بعد المصروفات: "+LedgerMath.money(LedgerMath.netActivity(rows)),14);totals.setTextColor(MUTED);summary.addView(totals);button(summary,"+ إضافة بند",()->entry(book),true);button(summary,"معاينة PDF",()->previewPdf(book,rows),false);button(summary,"مشاركة PDF",()->sharePdf(book,rows),false);button(summary,"تعديل اسم الدفتر أو الرصيد الافتتاحي",()->editBook(book),false);if(rows.isEmpty())muted("لا توجد بنود بعد. أضف تحصيلًا أو مصروفًا وسيُحدّث الرصيد فورًا.");for(JSONObject row:rows)entryCard(book,row);button(body,"العودة إلى الدفاتر",this::list,false);}
    private void entryCard(JSONObject book,JSONObject item){LinearLayout box=card();LinearLayout top=new LinearLayout(this);top.setOrientation(LinearLayout.HORIZONTAL);top.setGravity(Gravity.CENTER_VERTICAL);box.addView(top);TextView title=text(item.optString("title"),18);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));boolean income=item.optString("kind").equals("in");TextView amount=text((income?"+ ":"− ")+LedgerMath.money(new BigDecimal(item.optString("amount","0"))),18);amount.setTextColor(income?TEAL:0xffb45309);top.addView(amount);String marker=item.optString("marker"),method=income?" • "+LedgerMath.methodLabel(item.optString("paymentMethod","cash")):"";TextView info=text((marker.isEmpty()?"":marker+"  •  ")+android.text.format.DateFormat.format("yyyy-MM-dd HH:mm",item.optLong("at"))+method,13);info.setTextColor(MUTED);box.addView(info);if(!item.optString("note").isEmpty()){TextView note=text("ملاحظة: "+item.optString("note"),14);note.setTextColor(MUTED);box.addView(note);}button(box,"تعديل أو حذف",()->editEntry(book,item),false);}
    private void entry(JSONObject book){editEntry(book,new JSONObject());}
    private void editEntry(JSONObject book,JSONObject original){JSONObject copy;try{copy=new JSONObject(original.toString());}catch(Exception e){copy=new JSONObject();}final JSONObject item=copy;LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(20),dp(8),dp(20),dp(8));EditText title=field(f,"وصف العملية",item.optString("title"),false),amount=field(f,"المبلغ",item.optString("amount"),true),note=field(f,"ملاحظة مهمة للطباعة",item.optString("note"),false);Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"تحصيل","مصروف نقدي"}));type.setSelection(item.optString("kind").equals("out")?1:0);f.addView(text("نوع العملية",13));f.addView(type);Spinner payment=new Spinner(this);String[] methods={"كاش لدى المندوب","دفع شبكة للشركة","تحويل لحساب الشركة"};payment.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,methods));String[] methodKeys={"cash","network","transfer"};int paymentSelected=0;for(int i=0;i<methodKeys.length;i++)if(methodKeys[i].equals(item.optString("paymentMethod","cash")))paymentSelected=i;payment.setSelection(paymentSelected);f.addView(text("طريقة التحصيل (للوارد فقط)",13));f.addView(payment);Spinner marker=new Spinner(this);String[] marks={"بدون علامة","⭐ مهم","🔴 يحتاج مراجعة","✓ تم","✕ ملغي"};marker.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,marks));int selected=0;for(int i=0;i<marks.length;i++)if(marks[i].equals(item.optString("marker")))selected=i;marker.setSelection(selected);f.addView(text("علامة تذكير",13));f.addView(marker);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(item.optLong("id")>0?"تعديل بند":"إضافة بند").setView(f).setNegativeButton("إلغاء",null).setPositiveButton("حفظ",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(x->{try{item.put("notebookId",book.optLong("id")).put("title",title.getText().toString()).put("amount",amount.getText().toString()).put("kind",type.getSelectedItemPosition()==0?"in":"out").put("paymentMethod",type.getSelectedItemPosition()==0?methodKeys[payment.getSelectedItemPosition()]:"cash").put("marker",marker.getSelectedItemPosition()==0?"":marks[marker.getSelectedItemPosition()]).put("note",note.getText().toString()).put("at",item.optLong("at",System.currentTimeMillis()));store.saveLedgerEntry(item);dialog.dismiss();open(book.optLong("id"));}catch(Exception e){alert(e);}}));if(item.optLong("id")>0)dialog.setButton(AlertDialog.BUTTON_NEUTRAL,"حذف",(d,w)->new AlertDialog.Builder(this).setMessage("حذف هذا البند؟").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(a,b)->{store.removeLedgerEntry(item.optLong("id"));open(book.optLong("id"));}).show());dialog.show();}
    private void editBook(JSONObject original){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(20),dp(8),dp(20),dp(8));EditText name=field(f,"اسم الدفتر",original.optString("name"),false),opening=field(f,"الرصيد الافتتاحي",original.optString("openingBalance"),true);new AlertDialog.Builder(this).setTitle("بيانات الدفتر").setView(f).setNegativeButton("إلغاء",null).setPositiveButton("حفظ",(d,w)->{try{original.put("name",name.getText().toString()).put("openingBalance",opening.getText().toString());store.saveNotebook(original);open(original.optLong("id"));}catch(Exception e){alert(e);}}).setNeutralButton("حذف الدفتر",(d,w)->new AlertDialog.Builder(this).setMessage("سيُحذف الدفتر وكل بنوده نهائيًا.").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(a,b)->{store.removeNotebook(original.optLong("id"));list();}).show()).show();}
    private Uri ledgerPdfUri(JSONObject book,ArrayList<JSONObject> rows)throws Exception{java.io.File file=LedgerPdf.create(this,book,rows);return Uri.parse("content://"+getPackageName()+".quotes/"+file.getName());}
    private void previewPdf(JSONObject book,ArrayList<JSONObject> rows){try{Uri uri=ledgerPdfUri(book,rows);Intent preview=new Intent(this,QuotePreviewActivity.class).setDataAndType(uri,"application/pdf").putExtra("previewTitle","معاينة كشف الدفتر").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);preview.setClipData(android.content.ClipData.newRawUri("كشف دفتر",uri));startActivity(preview);}catch(Exception e){alert(e);}}
    private void sharePdf(JSONObject book,ArrayList<JSONObject> rows){try{Uri uri=ledgerPdfUri(book,rows);Intent send=new Intent(Intent.ACTION_SEND).setType("application/pdf").putExtra(Intent.EXTRA_STREAM,uri).putExtra(Intent.EXTRA_SUBJECT,"كشف "+book.optString("name")).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);send.setClipData(android.content.ClipData.newRawUri("كشف دفتر",uri));startActivity(Intent.createChooser(send,"مشاركة كشف الدفتر"));}catch(Exception e){alert(e);}}
    private void alert(Exception e){new AlertDialog.Builder(this).setMessage(e.getMessage()==null?"تعذر إتمام العملية":e.getMessage()).setPositiveButton("حسنًا",null).show();}
}
